#!/usr/bin/env python3
"""Install the frozen local Mind2Web assets from a directory or ZIP, without network access."""
from __future__ import annotations
import argparse
import hashlib
import io
import json
import os
import shutil
import sys
import tempfile
import zipfile
from pathlib import Path, PurePosixPath

# Keep generated bytecode off removable/cloud-coordinated project folders.
sys.pycache_prefix = os.environ.get('PYTHONPYCACHEPREFIX', str(Path(tempfile.gettempdir()) / ('eventpilot_v11_pycache_' + str(os.getuid() if hasattr(os, 'getuid') else 'user'))))

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from eventpilot.io import file_digest, read_json, read_jsonl, write_json


def required_assets(data):
    sources = read_json(data / 'sources.json')
    cases = list(read_jsonl(data / 'cases.jsonl'))
    ids = sorted({t['source_task_id'] for c in cases for t in c['tasks'].values()})
    assets = {'data/normalized/tasks.jsonl': None}
    manifest = read_json(data / 'manifest.json')
    assets['data/normalized/tasks.jsonl'] = manifest.get('source', {}).get('index_sha256')
    for tid in ids:
        source = sources[tid]
        hashes = source.get('audit', {}).get('snapshot_hashes', [])
        for i, step in enumerate(source['steps']):
            name = step['cleaned_html']
            relative = PurePosixPath(name)
            if relative.is_absolute() or '..' in relative.parts or not name.startswith('data/normalized/snapshots/'):
                raise ValueError('Unsafe registered asset path')
            assets[name] = hashes[i] if i < len(hashes) else None
    return assets, len(ids)


def safe_target(root, relative):
    target = (root / relative).resolve()
    if not target.is_relative_to(root.resolve()):
        raise ValueError('Asset path escapes corpus-root')
    return target


def atomic_copy(stream, target, expected):
    target.parent.mkdir(parents=True, exist_ok=True)
    fd, name = tempfile.mkstemp(prefix=target.name + '.', suffix='.tmp', dir=target.parent)
    h = hashlib.sha256()
    try:
        with os.fdopen(fd, 'wb') as output:
            while True:
                chunk = stream.read(1024 * 1024)
                if not chunk:
                    break
                output.write(chunk); h.update(chunk)
            output.flush(); os.fsync(output.fileno())
        if expected and h.hexdigest() != expected:
            raise ValueError('Source asset SHA256 mismatch: ' + target.name)
        os.replace(name, target)
    finally:
        if os.path.exists(name):
            os.unlink(name)


def verify(root, assets):
    missing, changed, size = [], [], 0
    packed=root/'snapshots.zip'
    archive=zipfile.ZipFile(io.BytesIO(packed.read_bytes())) if packed.is_file() else None
    members=set(archive.namelist()) if archive else set()
    for relative, sha in assets.items():
        if relative in members:
            raw=archive.read(relative)
            size+=len(raw)
            if sha and hashlib.sha256(raw).hexdigest()!=sha:changed.append(relative)
            continue
        target = safe_target(root, relative)
        if not target.is_file():
            missing.append(relative); continue
        size += target.stat().st_size
        if sha and file_digest(target) != sha:
            changed.append(relative)
    if archive:archive.close()
    return {'ok': not missing and not changed, 'files': len(assets), 'bytes': size,
            'snapshot_storage':'unchanged_html_in_local_zip' if packed.is_file() else 'individual_html_files',
            'missing': missing, 'changed': changed}


def install(data, target, source_dir=None, archive=None, check_only=False):
    assets, tasks = required_assets(data)
    target = Path(target).expanduser().resolve()
    if not check_only:
        target.mkdir(parents=True, exist_ok=True)
        if source_dir:
            source = Path(source_dir).expanduser().resolve()
            for i, (relative, sha) in enumerate(assets.items()):
                destination = safe_target(target, relative)
                if destination.is_file() and (not sha or file_digest(destination) == sha):
                    continue
                original = safe_target(source, relative)
                with original.open('rb') as stream:
                    atomic_copy(stream, destination, sha)
                if i % 100 == 0:
                    print(f'[DATA] {i + 1}/{len(assets)} files', flush=True)
            for name in ('ATTRIBUTION.md', 'upstream/Mind2Web_README.md'):
                if (source / name).is_file() and source != target:
                    destination = safe_target(target, name)
                    destination.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copyfile(source / name, destination)
        elif archive:
            with zipfile.ZipFile(archive) as z:
                members = {info.filename: info for info in z.infolist() if not info.is_dir()}
                indexes = [name for name in members if name.endswith('data/normalized/tasks.jsonl')]
                if len(indexes) != 1:
                    raise ValueError('Archive must contain one normalized task index')
                prefix = indexes[0][:-len('data/normalized/tasks.jsonl')]
                for i, (relative, sha) in enumerate(assets.items()):
                    destination = safe_target(target, relative)
                    if destination.is_file() and (not sha or file_digest(destination) == sha):
                        continue
                    member = prefix + relative
                    if member not in members:
                        raise ValueError('Archive is missing registered asset: ' + relative)
                    info = members[member]
                    # Symlink members are data, never filesystem links; only the
                    # exact allowlisted byte assets are copied.
                    if (info.external_attr >> 16) & 0o170000 == 0o120000:
                        raise ValueError('Symlink source asset is not allowed')
                    with z.open(info) as stream:
                        atomic_copy(stream, destination, sha)
                    if i % 100 == 0:
                        print(f'[DATA] {i + 1}/{len(assets)} files', flush=True)
                for relative in ('ATTRIBUTION.md', 'upstream/Mind2Web_README.md'):
                    member = prefix + relative
                    if member in members:
                        with z.open(member) as stream:
                            atomic_copy(stream, safe_target(target, relative), None)
        else:
            raise ValueError('Choose --from-directory, --from-archive, or --check-only')
    result = {'corpus_root': str(target), 'source_tasks': tasks, **verify(target, assets)}
    if not check_only and result['ok']:
        write_json(target / 'eventpilot_v11_assets.json', result)
    return result


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--data', type=Path, default=ROOT / 'data')
    p.add_argument('--corpus-root', type=Path, default=ROOT / 'corpus')
    group = p.add_mutually_exclusive_group()
    group.add_argument('--from-directory', type=Path)
    group.add_argument('--from-archive', type=Path)
    group.add_argument('--check-only', action='store_true')
    args = p.parse_args()
    result = install(args.data, args.corpus_root, args.from_directory, args.from_archive, args.check_only)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    if not result['ok']:
        raise SystemExit(2)


if __name__ == '__main__':
    main()
